-- Calendar integrity scan. READ-ONLY: nothing here changes data. Run it as ONE query: it returns a scorecard, one row per check.
-- found = 0 is healthy. "info" rows are counts to know about, not problems.
select * from (
  select 1 as n, 'info' as kind, 'events in total' as check_name, count(*)::int as found, 'All calendar events.' as meaning from public.events
  union all select 2, 'problem', 'ends before it starts', count(*)::int, 'Shows wrong on every page and can break sorting.' from public.events where ends_at is not null and ends_at < starts_at
  union all select 3, 'problem', 'start date outside 2025 to 2028', count(*)::int, 'Almost always a typo in the year; it will never be seen where expected.' from public.events where starts_at < '2025-01-01' or starts_at > '2029-01-01'
  union all select 4, 'problem', 'same title and start time entered more than once', coalesce(sum(c - 1), 0)::int, 'Duplicates, often from running an import twice.' from (select count(*) as c from public.events group by organization_id, title, starts_at having count(*) > 1) d
  union all select 5, 'problem', 'imported event present more than once', coalesce(sum(c - 1), 0)::int, 'The prepared-schedule import should never create the same event twice.' from (select count(*) as c from public.events where metadata->>'import_key' is not null group by organization_id, metadata->>'import_set', metadata->>'import_key' having count(*) > 1) d
  union all select 6, 'problem', 'gameplan event repeats an imported one (same model, type and day)', count(*)::int, 'The same visa day, arrival or stay shown twice on the model''s calendar.' from public.events g join public.event_models gm on gm.event_id = g.id join public.event_models im on im.model_id = gm.model_id join public.events i on i.id = im.event_id where g.metadata->>'plan' = 'g90' and i.metadata->>'import_key' is not null and g.event_type = i.event_type and (g.starts_at at time zone 'UTC')::date = (i.starts_at at time zone 'UTC')::date
  union all select 7, 'problem', 'shared with models but no model attached', count(*)::int, 'Nobody can see it on a model calendar.' from public.events e where e.visibility = 'model_shared' and not exists (select 1 from public.event_models m where m.event_id = e.id)
  union all select 8, 'problem', 'a model is attached but the event is private', count(*)::int, 'The model portal hides private events, so the model never sees it.' from public.events e where e.visibility = 'private' and exists (select 1 from public.event_models m where m.event_id = e.id)
  union all select 9, 'problem', 'a model is attached but the model calendar''s keyword filter hides it', count(*)::int, 'Attached and not private, yet it will not appear on the model''s calendar. Fix by switching on "Show on the model''s calendar".' from public.events e
    where exists (select 1 from public.event_models m where m.event_id = e.id) and e.visibility <> 'private' and coalesce(e.metadata->>'share_with_models', '') <> 'true'
      and (e.metadata->>'model_created') is distinct from 'true'
      and ( (coalesce(e.event_type,'') || ' ' || coalesce(e.title,'') || ' ' || coalesce(e.notes,'') || ' ' || coalesce(e.metadata->>'category','') || ' ' || coalesce(e.metadata->>'event_kind','')) ~* '\m(agent task|agent agenda|internal agenda|internal review|internal meeting|booker task|booker agenda|crm|finance|invoice|relationship|submission strategy|client follow.?up|agency admin|agent-only|staff only)\M'
         or (coalesce(e.event_type,'') || ' ' || coalesce(e.title,'') || ' ' || coalesce(e.notes,'') || ' ' || coalesce(e.metadata->>'category','') || ' ' || coalesce(e.metadata->>'event_kind','')) !~* '\m(casting|go.?see|fitting|booking|job|show|runway|test shoot|photoshoot|photo shoot|test|digital|polaroid|practice|training|walk practice|runway practice|rehearsal|model meeting|model-agent|agent meeting|meeting|model movement|movement|travel|flight|fly.?in|fly.?out|arrival|departure|airport|housing|check.?in|check.?out|visa appointment|consulate appointment|passport appointment|call time)\M' )
  union all select 10, 'problem', 'attached to an archived, released or inactive model', count(*)::int, 'Clutters the calendar with someone who is no longer on the roster.' from public.event_models em join public.models m on m.id = em.model_id where m.status ~* '^(archiv|releas|inactive|former)' or m.active is false
  union all select 11, 'info', 'events with no owner', count(*)::int, 'Nobody is responsible and they will not appear in anyone''s DaySilk.' from public.events where owner_member_id is null
  union all select 12, 'problem', 'owner is not an active staff member', count(*)::int, 'Owned by someone who has left or been disabled.' from public.events e where e.owner_member_id is not null and not exists (select 1 from public.organization_members om where om.id = e.owner_member_id and om.status = 'active')
  union all select 13, 'problem', 'agent task whose meeting no longer exists', count(*)::int, 'A task still open for a meeting that was deleted.' from public.tasks t where t.metadata->>'event_id' is not null and t.status not in ('completed','cancelled','done') and not exists (select 1 from public.events e where e.id::text = t.metadata->>'event_id')
  union all select 14, 'info', 'tasks linked to an event through tasks.event_id', count(*)::int, 'These are detached, not deleted, when the event is deleted from the portal.' from public.tasks where event_id is not null
  union all select 15, 'info', 'multi-day events (shown only on their first day in the Agenda)', count(*)::int, 'Stays and long trips. They disappear from later days.' from public.events where ends_at is not null and (ends_at at time zone 'UTC')::date > (starts_at at time zone 'UTC')::date
  union all select 16, 'problem', 'no time zone recorded', count(*)::int, 'Times can shift for people in other cities.' from public.events where timezone is null
  union all select 17, 'problem', 'a model double-booked (overlapping timed events)', count(*)::int, 'Two timed events overlap for the same model.' from public.events a join public.event_models am on am.event_id = a.id join public.event_models bm on bm.model_id = am.model_id and bm.event_id <> am.event_id join public.events b on b.id = bm.event_id where a.id < b.id and a.all_day is not true and b.all_day is not true and a.ends_at is not null and b.ends_at is not null and a.starts_at < b.ends_at and b.starts_at < a.ends_at and a.status <> 'cancelled' and b.status <> 'cancelled'
  union all select 18, 'info', 'travel events without a Mobility link', count(*)::int, 'Travel should be a Mobility record; these exist only on the calendar.' from public.events where event_type = 'travel' and metadata->>'travel_record_id' is null and metadata->>'mobility_travel_id' is null
  union all select 19, 'info', 'recurring events', count(*)::int, 'Edited as a series, not one by one.' from public.events where recurrence_rule is not null or metadata->>'repeat' is not null
  union all select 20, 'info', 'cancelled events still in the calendar', count(*)::int, 'Cancelled but not removed.' from public.events where status = 'cancelled'
) s order by n;
